mapper.select:
SELECT id, contract_id, customer_id, invoice_no, amount, invoice_date, invoice_type, status, remark,
       organization_id, create_user, update_user, create_time, update_time
FROM crm_invoice
WHERE organization_id = #{organizationId}

    AND (invoice_no LIKE CONCAT('%', #{keyword}, '%') OR remark LIKE CONCAT('%', #{keyword}, '%'))


    AND status = #{status}


    AND customer_id = #{customerId}

ORDER BY create_time DESC
